def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common color is the background; the other nonzero color is the pattern.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    pattern_color = next(c for c in counts if c not in (0, background))

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == pattern_color]
    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]
    ph, pw = max_r - min_r + 1, max_c - min_c + 1

    matches = []
    for r0 in range(h - ph + 1):
        for c0 in range(w - pw + 1):
            if all(grid[r0 + dr][c0 + dc] == 0 for dr, dc in shape):
                matches.append((r0, c0))

    out = [row[:] for row in grid]
    for r0, c0 in matches:
        for dr, dc in shape:
            out[r0 + dr][c0 + dc] = pattern_color
    return out
